const main=document.querySelector('main');
const concepts=[['Identidad','Tu identidad reúne tu historia, tus valores, tu personalidad, tus influencias y la manera en que elegís mostrarte. No es algo fijo: se construye, cambia y evoluciona con vos y con tu proyecto.'],['Identidad audiovisual','Tu identidad audiovisual se construye en la relación entre tu sonido, tu historia y las decisiones con las que te mostrás. El color, el vestuario, los encuadres, la iluminación y la forma de narrar pueden conectar piezas diferentes sin hacerlas idénticas.'],['Traducción intersemiótica','Es transformar significados de un lenguaje a otro. Una canción puede convertirse en una imagen, un gesto, una textura o una escena. Traducir entre lenguajes no es ilustrar cada palabra: es elegir recursos visuales que expresan el universo de tu música.'],['Universo artístico','Es la red de elementos que construyen tu mundo como artista: música, imagen, narrativa, performance, símbolos y formas de comunicar. Aunque cambien los formatos, estos elementos ayudan a que tu proyecto siga siendo reconocible.'],['Coherencia identitaria','Es mantener una conexión entre las distintas piezas y plataformas sin que todo tenga que verse igual. La coherencia aparece cuando ciertos elementos visuales, narrativos, conceptuales o simbólicos se sostienen y permiten reconocer el proyecto.'],['Narrativas transmedia','Es expandir un mismo universo a través de distintos medios y plataformas, donde cada contenido aporta algo nuevo. No se trata de repetir lo mismo, sino de ampliar la historia y la experiencia del artista. Cada plataforma puede aportar una parte nueva de tu universo.'],['Convergencia de medios','Es la forma en que tus contenidos circulan y se conectan entre distintas plataformas y formatos. Tu identidad puede desarrollarse en Instagram, YouTube, videoclips, shows, entrevistas y otros espacios que funcionan de manera complementaria.'],['Cultura participativa','Tu audiencia no solo mira lo que hacés: también comenta, comparte, interpreta y recrea tus contenidos. Tu identidad también se construye en ese intercambio. Escuchar a tu comunidad puede ayudarte a entender qué conecta, sin perder tu propia mirada.']];
const lessons=[
{cat:'Fotografía',title:'Una sesión con tu propio universo',intro:'Antes de sacar la foto, decidí qué querés que se sienta.',steps:['Elegí tres palabras que describan la canción o etapa que vas a comunicar.','Buscá una locación, un objeto y un vestuario que dialoguen con esas palabras.','Limpia la lente y probá un plano abierto, uno medio y un detalle. Prestá atención al fondo.','Seleccioná una serie por su coherencia: luz, color, gestos y encuadres.'],task:'Hacé una serie de tres fotos que puedan convivir como portada, publicación y detrás de escena.'},
{cat:'Iluminación',title:'Una ventana, muchas posibilidades',intro:'La dirección de la luz cambia la sensación de una imagen.',steps:['Ubicate cerca de una ventana y apagá luces que generen mezclas de color no deseadas.','Probá la luz de frente y luego de costado. Compará las sombras del rostro.','Usá una pared clara o cartón blanco para suavizar sombras si lo necesitás.','Grabá una prueba y revisá que las zonas claras conserven detalle.'],task:'Registrá el mismo fragmento con dos posiciones de luz. Elegí la que mejor acompañe la emoción de tu música.'},
{cat:'Edición',title:'Dale ritmo a lo que mostrás',intro:'La edición también cuenta quién sos: no todos los cortes necesitan seguir el golpe musical. Podés usar aplicaciones gratuitas como CapCut, Edits o Canva, entre otras.',steps:['Definí una idea central para la pieza antes de ordenar los clips.','Armá una primera secuencia con un inicio, un desarrollo y un cierre.','Probá alternar planos y duraciones según la energía de la canción.','Sumá texto legible cuando aporte información. Revisá la pieza con y sin sonido.'],task:'Editá dos versiones de una misma secuencia: una contemplativa y otra dinámica. Compará qué cambia en el sentido.'},
{cat:'Hooks',title:'Un comienzo que invite a quedarse',intro:'Abrí una pregunta, una emoción o una imagen que tenga sentido para tu proyecto.',steps:['Identificá qué tiene de singular lo que vas a mostrar: una letra, un sonido o una historia.','Probá empezar con ese elemento, evitando una introducción larga.','Construí un desarrollo que cumpla lo que el comienzo promete.','Cerrá con una invitación concreta: escuchar, comentar o conocer otra parte de la historia.'],task:'Escribí tres comienzos para un mismo video: una frase de la letra, una pregunta personal y una imagen inesperada.'}
];
function startWithSection(){return `<section class="start-with" aria-labelledby="start-with-title"><div class="start-with-heading"><p class="eyebrow">PRIMEROS PASOS</p><h2 id="start-with-title">Empezá con lo que tenés:</h2><p>Construir una identidad audiovisual no requiere empezar con una cámara profesional, un estudio o un equipo grande. Muchas veces, una buena idea y una decisión visual clara pueden tener más impacto que una producción costosa.</p></div><ol class="start-with-list"><li><strong>Usá tu celular:</strong> con la cámara del teléfono ya podés crear reels, fotos, videoclips simples, registros en vivo, backstage y contenido cotidiano.</li><li><strong>Aprovechá la luz natural:</strong> una ventana, el atardecer o una locación exterior pueden ayudarte a generar imágenes atractivas sin equipamiento de iluminación.</li><li><strong>Buscá locaciones disponibles:</strong> tu habitación, una terraza, una plaza, una calle o la casa de un amigo pueden convertirse en parte de tu universo visual si están elegidas con intención.</li><li><strong>Trabajá con lo que ya tenés:</strong> ropa, accesorios, objetos personales, instrumentos y elementos cotidianos pueden transformarse en recursos identitarios.</li><li><strong>Prioriza el concepto:</strong> antes de pensar cuánto podés gastar, definí qué querés transmitir. Una idea clara ayuda a tomar mejores decisiones sobre color, encuadre, vestuario y edición.</li><li><strong>Reutilizá una producción:</strong> una misma jornada puede darte fotos, reels, historias, fragmentos de videoclip, portada, backstage y contenido para distintos momentos.</li><li><strong>No esperes a tener todo perfecto:</strong> empezar a crear también te permite descubrir qué funciona, qué te representa y qué elementos querés seguir desarrollando.</li></ol><div class="start-with-review"><h3>Después mirá el resultado y pregúntate:</h3><ol><li>¿Esto se siente como mi proyecto?</li><li>¿Qué elemento me representa más?</li><li>¿Qué mantendría en próximos contenidos?</li><li>¿Qué cambiaría o probaría diferente?</li></ol></div></section>`}
