function profilesSection(accent='cyan'){return `<section data-profile-panel hidden class="creative-profiles accent-border-${accent}" aria-labelledby="creative-profiles-title"><div class="profiles-intro"><p class="eyebrow">RECOMENDACIONES / PERFILES CREATIVOS</p><h2 id="creative-profiles-title">Seguí aprendiendo con otras miradas.</h2><p>Una selección de perfiles para sumar ideas, técnicas y recursos a tu identidad artística.</p></div><div class="profile-grid">${creativeProfiles.map(p=>`<article class="profile-card"><header class="profile-card-head"><div><h3>${p.name}</h3><p class="profile-level">${p.level}</p></div><a class="profile-handle" href="${p.url}" target="_blank" rel="noopener noreferrer" aria-label="Ver ${p.name} en Instagram">Instagram · ${p.handle} ↗</a></header><dl><div><dt>Ideal para</dt><dd>${p.ideal}</dd></div><div><dt>¿Qué necesitás?</dt><dd>${p.needs}</dd></div><div class="profile-purpose"><dt>Te puede servir para</dt><dd>${p.use}</dd></div></dl></article>`).join('')}</div></section>`}
