function conceptPage(){return head('01 / CONCEPTOS','Conceptos<br>clave.','Ocho ideas para entender cómo se construye un universo artístico y empezar a tomar decisiones propias.')+`<div class="content concept-list">${concepts.map((c,i)=>`<article class="concept-row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h2>${c[0]}</h2></div><div><p>${c[1]}</p></div></article>`).join('')}<div class="next"><h2>De las ideas a tu proyecto.</h2><a class="pill" href="#guia">Empezá tu guía ⟶</a></div></div>`}
function tutorialPage(){return head('04 / TUTORIALES','Creá con lo<br>que tenés.','Ejercicios prácticos de fotografía, iluminación, edición y hooks para darle forma a tu universo visual.','cyan')+`<div class="content">${startWithSection()}<div class="tutorial-library"><p class="eyebrow">TUTORIALES PRÁCTICOS</p><div class="filter" aria-label="Filtrar tutoriales">${['Todos','Fotografía','Iluminación','Edición','Hooks','Perfiles creativos'].map((c,i)=>`<button data-filter="${c}" class="${i?'':'selected'}" aria-pressed="${!i}">${c}</button>`).join('')}</div><div id="lessons">${lessons.map(l=>`<details class="lesson" data-category="${l.cat}"><summary><span class="label">${l.cat}</span><h2>${l.title}</h2></summary><div class="lesson-body"><p>${l.intro}</p><ol>${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="exercise"><b>Ahora probá vos:</b><p>${l.task}</p></div></div></details>`).join('')}</div>${profilesSection('cyan')}</div></div>`}
